import{ROOMS,ITEMS,initial,hydrate,event,canTravel,objective,chapter,D}from'./story.mjs';
import{Soundscape}from'./audio.mjs';import{icon}from'./icons.mjs';import{createPuzzles}from'./puzzles.mjs';
const $=s=>document.querySelector(s),KEY='blindspot-investigation-v2',sound=new Soundscape();let s=initial();try{s=hydrate(JSON.parse(localStorage.getItem(KEY)));}catch{}
let busy=false,target=null,arrival=null,lastTick=0,walkClock=0,walkSpeed=0,typing=0,typeTimer=0,toastTimer=0,saveTimer=0,modalCleanup=null;
const sceneCache=new Map();
function loadScene(room){
 if(sceneCache.has(room))return sceneCache.get(room);
 const attempt=retry=>new Promise((resolve,reject)=>{
  const img=new Image();img.alt=ROOMS[room].name;img.id='background';
  let done=false;
  const finish=error=>{if(done)return;done=true;clearTimeout(timer);img.onload=img.onerror=null;if(error)reject(error);else resolve(img);};
  const timer=setTimeout(()=>finish(new Error('scene timeout')),20000);
  img.onerror=()=>finish(new Error('scene unavailable'));
  img.onload=()=>{if(!img.naturalWidth){finish(new Error('empty scene'));return;}
   // A loaded image remains usable if the optional decode hint rejects.
   if(img.decode)Promise.race([img.decode().catch(()=>{}),new Promise(r=>setTimeout(r,500))]).then(()=>finish());else finish();
  };
  img.src=new URL('assets/'+ROOMS[room].image,import.meta.url).href+(retry?'?retry=1':'');
 });
 const promise=attempt(false).catch(()=>attempt(true)).catch(error=>{sceneCache.delete(room);throw error;});
 sceneCache.set(room,promise);return promise;
}
function mountScene(img){if($('#background')!==img)$('#background').replaceWith(img);}
const frames=[1,2,3,2];const esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const dom=$('#modal');
function save(){try{localStorage.setItem(KEY,JSON.stringify(s));$('#save-state').textContent='已记录';$('#save-state').style.opacity='.7';clearTimeout(saveTimer);saveTimer=setTimeout(()=>$('#save-state').style.opacity=0,1400);}catch{$('#save-state').textContent='当前浏览器无法保存进度';$('#save-state').style.opacity=1;}}
function notify(text){$('#toast').textContent=text;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3600);}
function commit(name,value){const r=event(s,name,value);if(r.ok){s=r.state;save();render();}return r.ok;}
function open(html,setup){stopWalking();modalCleanup?.();modalCleanup=null;$('#modal-content').innerHTML=html;$('#close-modal').hidden=false;if(!dom.open)dom.showModal();$('#game').classList.add('inspecting');const c=setup?.();if(typeof c==='function')modalCleanup=c;}
function close(){modalCleanup?.();modalCleanup=null;dom.close();$('#game').classList.remove('inspecting');}
$('#close-modal').onclick=close;dom.addEventListener('cancel',()=>{modalCleanup?.();modalCleanup=null;$('#game').classList.remove('inspecting');});
function say(lines,after=null){stopWalking();s.dialogue={lines,index:0,after};save();displayLine(true);}
function displayLine(log=false){const d=s.dialogue;if(!d)return;const [who,text]=d.lines[d.index];$('#dialogue').hidden=false;$('#choices').hidden=true;$('#speaker').textContent=who;$('#dialogue').classList.toggle('system-speaking',['系统','终端','终端缓存','未删除记录'].includes(who));$('#line-count').textContent=`${d.index+1} / ${d.lines.length}`;$('#speech').textContent='';$('#dialogue').classList.add('speaking');typing=0;clearInterval(typeTimer);if(log){s.history.push([who,text]);s.history=s.history.slice(-120);save();}if(s.settings.reduced||window.matchMedia('(prefers-reduced-motion: reduce)').matches){typing=text.length;$('#speech').textContent=text;$('#dialogue').classList.remove('speaking');}else typeTimer=setInterval(()=>{typing=Math.min(text.length,typing+1);$('#speech').textContent=text.slice(0,typing);if(typing===text.length){clearInterval(typeTimer);$('#dialogue').classList.remove('speaking');}},28);$('#continue-label').textContent='点击文本框 · 显示全部 / 继续';}
function advance(){if(!s.dialogue||dom.open||busy)return;const d=s.dialogue,text=d.lines[d.index][1];if(typing<text.length){clearInterval(typeTimer);typing=text.length;$('#speech').textContent=text;$('#dialogue').classList.remove('speaking');return;}sound.fx();if(d.index<d.lines.length-1){d.index++;displayLine(true);}else{const after=d.after;s.dialogue=null;clearInterval(typeTimer);$('#dialogue').hidden=true;save();render();afterDialogue(after);}}
$('#dialogue').onclick=advance;$('#dialogue').onkeydown=e=>{if(e.code==='Enter'){e.preventDefault();e.stopPropagation();advance();}};
function choose(options){$('#dialogue').hidden=true;$('#choices').hidden=false;$('#choices').innerHTML=options.map((o,i)=>`<button class="choice" data-choice="${i}">${esc(o.label)}${o.sub?`<small>${esc(o.sub)}</small>`:''}</button>`).join('');document.querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>{$('#choices').hidden=true;options[+b.dataset.choice].run();});}
function afterDialogue(after){if(after==='response')responseChoice();if(after==='ending')endingChoice();if(after==='showEnd')endScreen();}
function responseChoice(){if(s.flags.response)return;choose([{label:'追问：考勤钟不会说谎。',sub:'让系统知道，你已经发现了矛盾。',run:()=>{commit('challenge');glitch();say(D.challenge);}},{label:'保持沉默，自己检查。',sub:'暂时不暴露你的怀疑。',run:()=>{commit('silent');say(D.silent);}}]);}
function endingChoice(){choose([{label:'秘密复制原始记录',sub:'保留证据，带着疑问继续寻找林岑。',run:()=>{commit('ending','copy');say([['维护员','不在这里争辩。先把不能被修改的东西带走。'],['旁白','相机与纸张被收进外套。走廊没有响起警报。'],['维护员','B3。下一次，我会先确认是谁在替我点头。']],'showEnd');}},{label:'广播给所有夜班终端',sub:'立即公开记录，同时暴露自己的位置。',run:()=>{commit('ending','broadcast');glitch();sound.fx('glitch');say([['终端','原始记录已发送至 47 台夜班终端。'],['旁白','门外响起急促的脚步声。屏幕上，一个又一个“已读”亮起。'],['维护员','他们现在知道，我也知道。再也不是我一个人看见了。']],'showEnd');}}]);}
function stopWalking(){target=null;arrival=null;$('#actor').classList.remove('walking');$('#actor-image').style.setProperty('--frame',0);walkClock=0;walkSpeed=0;}
function walk(x,callback){if(busy||dom.open||s.dialogue||!$('#choices').hidden||!s.started)return;target=Math.max(5,Math.min(95,x));arrival=callback||null;$('#actor').style.setProperty('--facing',target<s.x?-1:1);$('#actor').classList.add('walking');$('#destination').style.left=target+'%';$('#destination').classList.remove('visible');void $('#destination').offsetWidth;$('#destination').classList.add('visible');}
function tick(now){const dt=Math.min((now-lastTick)/1000,.05)||0;lastTick=now;if(target!==null&&!dom.open&&!busy&&!document.hidden){const dx=target-s.x;walkSpeed+=(Math.min(23,Math.max(5,Math.abs(dx)*9))-walkSpeed)*Math.min(1,dt*12);const step=dt*walkSpeed;if(Math.abs(dx)<=step){s.x=target;const cb=arrival;stopWalking();save();cb?.();}else{s.x+=Math.sign(dx)*step;walkClock+=dt*(walkSpeed/23);const n=frames[Math.floor(walkClock/.13)%4];if($('#actor-image').style.getPropertyValue('--frame')!==String(n)){$('#actor-image').style.setProperty('--frame',n);if(n===1||n===3)sound.fx('step');}}$('#actor').style.left=s.x+'%';$('#scene').style.setProperty('--parallax',`${(50-s.x)*.08}px`);}requestAnimationFrame(tick);}requestAnimationFrame(tick);
async function travel(room){
 if(busy||room===s.room)return;
 if(!canTravel(s,room)){say([['维护员',room==='archive'?'磁条门禁。需要一张还能使用的旧卡。':'先拍下设备，再把胶片带进去。']]);return;}
 stopWalking();busy=true;
 const reduced=s.settings.reduced||window.matchMedia('(prefers-reduced-motion: reduce)').matches;
 const fade=reduced?0:220;
 $('#transition-name').textContent=ROOMS[room].name;$('#transition-sub').textContent=ROOMS[room].sub;
 $('#transition').classList.add('active');sound.fx('door');
 const loading=setTimeout(()=>$('#transition-sub').textContent='正在准备场景…',800);
 try{
  const [img]=await Promise.all([loadScene(room),delay(fade)]);
  clearTimeout(loading);mountScene(img);
  s.room=room;s.x=room==='darkroom'?80:room==='archive'?90:room==='lounge'?85:12;
  s.seen=[...new Set([...s.seen,room])];render();try{sound.setRoom(room);}catch(error){console.warn('Ambient audio unavailable',error);}save();
  await new Promise(resolve=>requestAnimationFrame(()=>requestAnimationFrame(resolve)));
 }catch(error){
  console.error('Scene transition failed',room,error);clearTimeout(loading);notify('场景暂时未能载入，已留在原地。请再次点击入口重试。');
  $('#transition').classList.remove('active');busy=false;return;
 }
 $('#transition').classList.remove('active');await delay(fade);busy=false;
 if(room==='darkroom'&&!s.flags.enteredDarkroom){s.flags.enteredDarkroom=true;save();say(D.darkroom);}
 if(room==='archive'&&!s.flags.enteredArchive){s.flags.enteredArchive=true;save();say([['维护员','纸张的味道，像另一个年代。'],['系统','本区域记录可能过期。请以视觉辅助为准。']]);}
}
const delay=t=>new Promise(r=>setTimeout(r,t));function glitch(){$('#game').classList.remove('glitch');void $('#game').offsetWidth;$('#game').classList.add('glitch');sound.fx('glitch');}
const puzzles=createPuzzles({get:()=>s,commit,say,open,close,notify,fx:t=>sound.fx(t),glitch,readItem,afterDialogue});
function render(){const roomId=s.room,room=ROOMS[roomId];loadScene(roomId).then(img=>{if(s.room===roomId)mountScene(img);}).catch(()=>{});$('#location').textContent=room.name;$('#location-sub').textContent=room.sub+' · '+room.time;$('#chapter').textContent=chapter(s);$('#goal').textContent=objective(s);$('#signal').textContent=s.flags.isolated?'视觉辅助 / 离线':s.room==='darkroom'?'信号屏蔽 / 安静':s.suspicion?'校正等级 / 已提高':'视觉辅助 / 在线';$('#actor').style.left=s.x+'%';$('#rain').hidden=s.room!=='lounge';$('#game').classList.toggle('reduced',s.settings.reduced);$('#game').classList.toggle('no-markers',!s.settings.markers);$('#hotspots').innerHTML=room.spots.map(([id,label,x,y])=>`<button class="hotspot ${s.seen.includes(s.room+':'+id)?'visited':''}" style="left:${x}%;top:${y}%" data-spot="${id}" data-x="${x}" aria-label="${label}">${icon(ROOMS[id]?'door':'diamond')}<span class="spot-label">${label}</span></button>`).join('');document.querySelectorAll('[data-spot]').forEach(b=>b.onclick=e=>{e.stopPropagation();if(s.dialogue){advance();return;}walk(+b.dataset.x,()=>interact(b.dataset.spot));});const physical=s.items.filter(i=>['note','camera','badge','film','photo'].includes(i));$('#inventory').innerHTML=physical.map((id,i)=>`<button class="item-slot" data-item="${id}" data-label="${ITEMS[id].name}" aria-label="查看${ITEMS[id].name}">${['camera','photo'].includes(id)?`<img src="assets/${id}.png" alt="">`:icon(ITEMS[id].kind)}<em>${i+1}</em></button>`).join('');document.querySelectorAll('[data-item]').forEach(b=>b.onclick=()=>readItem(b.dataset.item));}
function interact(id){if(busy||s.dialogue||dom.open)return;s.seen=[...new Set([...s.seen,s.room+':'+id])];save();if(ROOMS[id]){travel(id);return;}if(id==='coffee'){if(!s.flags.coffee){commit('coffee');say(D.coffee);}else say([['维护员','杯子依旧留在原处。有人急着离开，连外套都没拿。']]);}else if(id==='clock'){commit('clock');say(D.clock);}else if(id==='terminal'){if(!s.flags.coffee||!s.flags.clock)say([['终端','该员工已离职。'],['维护员','先检查一下他留在这里的物品。']]);else if(!s.flags.terminal){commit('terminal');say(D.terminal,'response');}else if(!s.flags.response)responseChoice();else say([['终端缓存','「密码是我最后一次到岗的时间。」'],['维护员','机械考勤钟的记录已经收进手记。工具柜在机房。']]);}else if(id==='locker'){if(!s.flags.terminal)say([['维护员','密码锁。林岑或许留下过提示。先检查休息区的终端。']]);else if(!s.flags.locker)puzzles.keypad();else readItem('note');}else if(id==='cabinet'){if(s.flags.isolated)say([['维护员','干扰支路已经隔离。去档案室看看恢复的原始记录。']]);else if(s.flags.deduced)puzzles.circuit();else if(s.flags.locker&&!s.flags.photo)puzzles.camera();else say([['系统','C-07 状态正常。'],['维护员',s.flags.photo?'胶片还藏着答案。先冲洗，再核对纸质记录。':'看起来没有异常。但林岑不会无缘无故消失。']]);}else if(id==='files'){commit('files');say(D.files);}else if(id==='logs'){if(s.flags.isolated)say(D.final,'ending');else if(!s.flags.files)say([['维护员','终端上的编号太多了。先找一份纸质工单来对照。']]);else if(!s.flags.logs)puzzles.logs();else readItem('logs');}else if(id==='window')say(D.window);else if(id==='manual'){commit('manual');readItem('manual');}else if(id==='tray'){if(s.flags.developed)puzzles.photo();else if(!s.flags.manual){say([['维护员','冲洗台旁边有一本旧手册。先弄清楚操作顺序。']]);}else puzzles.develop();}else if(id==='board'){if(s.flags.developed&&s.clues.length<2)puzzles.photo();else puzzles.deduction();}render();}
function readItem(id){sound.fx('paper');if(id==='photo'){puzzles.photo();return;}const item=ITEMS[id];if(!item)return;open(`<span class="overline">随身记录 / ${esc(item.name)}</span><h2>${esc(item.name)}</h2><div class="item-detail">${item.kind==='camera'?'<img src="assets/camera.png" alt="胶片相机">':icon(item.kind)}<p>${esc(item.text)}</p></div><div class="actions"><button id="item-back" class="btn">收好</button></div>`,()=>{$('#item-back').onclick=close;});}
function map(){open(`<span class="overline">二层 / 维护区域</span><h2>今晚，你去过哪里？</h2><div class="map-grid">${Object.entries(ROOMS).map(([id,r])=>`<button class="map-room ${id===s.room?'current':''} ${!canTravel(s,id)?'locked':''}" data-room="${id}" ${!canTravel(s,id)?'disabled':''}><img src="assets/${r.image}" alt=""><strong>${r.name}</strong><small>${id===s.room?'当前位置':!canTravel(s,id)?(id==='archive'?'需要旧门禁卡':'先拍摄设备'):'前往这里'}</small></button>`).join('')}</div><p class="muted">${esc(objective(s))}</p>`,()=>document.querySelectorAll('[data-room]').forEach(b=>b.onclick=()=>{if(s.dialogue||!$('#choices').hidden){notify('先完成这段对白与选择。');return;}close();travel(b.dataset.room);}));}
function journal(tab='clues'){open(`<span class="overline">只有留下来的，才不会被撤回。</span><h2>调查手记</h2><div class="tabs"><button data-tab="clues" class="${tab==='clues'?'active':''}">线索 ${s.items.length}</button><button data-tab="dialogue" class="${tab==='dialogue'?'active':''}">对白回顾</button></div><div class="journal-list">${tab==='clues'?(s.items.length?s.items.map(i=>`<div class="journal-entry"><b>${ITEMS[i].name}</b><p>${esc(ITEMS[i].text)}</p></div>`).join(''):'<p class="muted">遗留物、纸张和照片，会保留在这里。</p>'):s.history.map(([who,text])=>`<div class="journal-entry"><b>${esc(who)}</b><p>${esc(text)}</p></div>`).join('')}</div>`,()=>document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>journal(b.dataset.tab)));}
function settings(){open(`<span class="overline">暂停 / 当前进度已记录</span><h2>留一点安静</h2><div class="settings-row"><span>背景音乐、环境声与音效</span><button id="sound-toggle">${s.settings.sound?'开启':'关闭'}</button></div><div class="settings-row"><span>减少动画与闪烁</span><button id="motion-toggle">${s.settings.reduced?'开启':'关闭'}</button></div><div class="settings-row"><span>显示调查标记</span><button id="markers-toggle">${s.settings.markers?'开启':'关闭'}</button></div><p class="muted">点击文本框：先补全本句，再次点击继续。空格 / Enter 也可以。A、D 或方向键移动，E 调查最近的物体。按住 Alt 临时显示物品名称。</p><div class="actions"><button class="btn primary" id="resume">继续调查</button><button class="btn" id="fullscreen">全屏</button><button class="btn" id="restart">重新开始</button></div>`,()=>{$('#resume').onclick=close;$('#sound-toggle').onclick=()=>{s.settings.sound=!s.settings.sound;sound.setEnabled(s.settings.sound);save();settings();};$('#motion-toggle').onclick=()=>{s.settings.reduced=!s.settings.reduced;save();render();settings();};$('#markers-toggle').onclick=()=>{s.settings.markers=!s.settings.markers;save();render();settings();};$('#fullscreen').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await $('#game').requestFullscreen();}catch{notify('当前浏览器暂不支持全屏。');}};$('#restart').onclick=confirmRestart;});}
function confirmRestart(){open('<h2>重新走进这个夜班？</h2><p>当前扩展版的调查进度会被清除。</p><div class="actions"><button class="btn primary" id="confirm-new">重新开始</button><button class="btn" id="cancel-new">继续当前调查</button></div>',()=>{$('#cancel-new').onclick=close;$('#confirm-new').onclick=()=>{close();stopWalking();clearInterval(typeTimer);s=initial();$('#choices').hidden=true;$('#dialogue').hidden=true;save();begin(true);};});}
function hint(){const f=s.flags;let key='start',h=['看看杯子，再检查左侧独立运转的机械考勤钟。','两件物品都检查后，再看工位终端。'];if(f.terminal&&!f.locker){key='locker';h=['密码与林岑最后一次到岗有关。数字来自不会联网的设备。','手记里的考勤记录是 02:17。去机房输入四位时间：0217。'];}else if(f.locker&&!f.photo){key='camera';h=['点击机房右侧的 C-07，用相机取景。需要构图与焦距同时合适。','取景中心约 72，焦距约 63。看到“影像清晰”后按快门。'];}else if(f.photo&&!f.developed){key='develop';h=['进入旧测试室，先阅读左侧冲洗手册。','密封罐处理后，曝光 2.7 至 3.6 秒。再按显影、停显、定影的顺序处理。'];}else if(f.developed&&s.clues.length<2){key='photo';h=['沿照片下半部的线路观察。寻找熟悉的固定方式，以及多出来的东西。','下方中央的线束固定件，与右下方模块各有一处可调查区域。'];}else if(f.developed&&(!f.files||!f.logs)){key='logs';h=['休息区的门禁卡能打开档案室。纸质工单与终端记录可以互相核对。','先调查档案室左侧纸质工单，再查看终端。你 01:40 已签退，02:17 的签名施工记录产生了矛盾。'];}else if(f.developed&&!f.deduced){key='deduce';h=['到旧测试室的“整理证据”处，把照片、工单和记录放在一起。','签名属于你，记忆却空缺，照片也与肉眼不符。系统修改了感知与部分记忆。'];}else if(f.deduced&&!f.isolated){key='circuit';h=['在 C-07 的线路草图中，沿左边输入、向下、再向右、最后向上接到模块。','三个接点分别需要：A 左＋下，B 上＋右，C 左＋上。通路核对后才能扳动隔离器。'];}else if(f.isolated){key='end';h=['回到档案室。信号断开后，原始记录已经恢复。','点击归档终端，读完记录后作出最后的选择。'];}const level=Math.min(s.hintLevel[key]||0,1);open(`<div class="hint-panel"><span class="overline">思路 ${level+1} / 2</span><h2>再想一步</h2><p>${h[level]}</p><div class="actions"><button class="btn primary" id="hint-close">我再试试</button>${level===0?'<button class="btn" id="more-hint">给我更明确的提示</button>':''}</div></div>`,()=>{$('#hint-close').onclick=close;if($('#more-hint'))$('#more-hint').onclick=()=>{s.hintLevel[key]=1;save();hint();};});}
function endScreen(){open(`<div class="ending-view"><span class="overline">${s.ending==='copy'?'结局一 / 无声的证人':'结局二 / 四十七个已读'}</span><h2>${s.ending==='copy'?'你带走了无法撤回的真相。':'这一次，所有人都看见了。'}</h2><img src="assets/camera.png" alt="胶片相机"><p>${s.ending==='copy'?'警报没有响起。林岑的去向留在纸上，而你自己的签名，仍然没有答案。':'原始记录传遍夜班终端。门外的脚步声越来越近，但证据已经不再属于你一个人。'}</p><p class="muted">${s.flags.response==='challenge'?'系统曾记录你的质疑。下一次校正，你的名字会排在前面。':'你曾选择沉默。这让系统低估了你的判断。'}</p><div class="stats"><span>四个场景</span><span>两处影像证据</span><span>判断修正 ${s.mistakes} 次</span></div><div class="actions"><button class="btn primary" id="end-replay">重新调查</button><button class="btn" id="end-log">回顾手记</button><button class="btn" id="end-other">回到最后的选择</button></div></div>`,()=>{$('#end-replay').onclick=confirmRestart;$('#end-log').onclick=()=>journal();$('#end-other').onclick=()=>{close();s.ending=null;save();endingChoice();};});}
function begin(fresh=false){s.started=true;s.seen=[...new Set([...s.seen,s.room])];$('#title-screen').hidden=true;$('#game').classList.remove('title-mode');sound.enabled=s.settings.sound;sound.room=s.room;sound.start();render();save();if(fresh||(!s.history.length&&!s.dialogue))say(D.intro);else if(s.dialogue)displayLine(false);else if(s.ending)endScreen();else if(s.flags.terminal&&!s.flags.response)responseChoice();}
$('#map-button').innerHTML=icon('map')+'<span>地图</span>';$('#journal-button').innerHTML=icon('book')+'<span>手记</span>';$('#settings-button').innerHTML=icon('settings')+'<span>设置</span>';$('#map-button').onclick=map;$('#journal-button').onclick=()=>journal();$('#settings-button').onclick=settings;$('#goal').onclick=()=>notify(objective(s));$('#hint-button').onclick=hint;$('#begin').onclick=()=>begin();$('#new-game').onclick=confirmRestart;
$('#world').onclick=e=>{if(s.dialogue){advance();return;}if(e.target.closest('button'))return;const r=$('#scene').getBoundingClientRect();walk((e.clientX-r.left)/r.width*100);};
document.addEventListener('keydown',e=>{if(e.altKey)$('#game').classList.add('show-markers');if(e.target.matches('input,textarea,select')||dom.open||!s.started||!$('#title-screen').hidden)return;if(e.target.closest('button')&&['Enter','Space'].includes(e.code))return;if(['Space','Enter','ArrowLeft','ArrowRight'].includes(e.code))e.preventDefault();if(e.code==='Space'||e.code==='Enter'){advance();return;}if(s.dialogue||busy||!$('#choices').hidden)return;if(e.code==='KeyA'||e.code==='ArrowLeft')walk(Math.max(5,(target??s.x)-8));if(e.code==='KeyD'||e.code==='ArrowRight')walk(Math.min(95,(target??s.x)+8));if(e.code==='KeyE'){const near=[...document.querySelectorAll('[data-spot]')].sort((a,b)=>Math.abs(+a.dataset.x-s.x)-Math.abs(+b.dataset.x-s.x))[0];near?.click();}if(e.code==='KeyM')map();if(e.code==='KeyJ')journal();if(e.code==='Escape')settings();});document.addEventListener('keyup',e=>{if(!e.altKey)$('#game').classList.remove('show-markers');});window.addEventListener('blur',()=>{$('#game').classList.remove('show-markers');stopWalking();});document.addEventListener('visibilitychange',()=>{if(document.hidden){sound.ctx?.suspend();save();}else if(s.settings.sound)sound.ctx?.resume();});
$('#rain').innerHTML=Array.from({length:25},(_,i)=>`<i style="left:${i*4}%;animation-delay:${-(i%7)*.19}s;animation-duration:${.8+(i%5)*.15}s"></i>`).join('');$('#dust').innerHTML=Array.from({length:12},(_,i)=>`<i style="left:${8+i*7}%;top:${24+(i*13)%50}%;animation-delay:${-i}s"></i>`).join('');
loadScene(s.room).catch(()=>notify('场景暂时未能载入，请刷新重试。'));
for(const room of Object.keys(ROOMS))loadScene(room).catch(()=>{});
render();if(s.started){$('#begin').innerHTML='继续调查 <span>→</span>';$('#new-game').hidden=false;}for(const file of ['walk-atlas.webp','ai-portrait.webp','photo.png','camera.png','portrait.png']){const img=new Image();img.src='assets/'+file;img.onerror=()=>notify('部分画面未能载入，请刷新后重试。');}

